-- ec_add_tb.vhd
-- Self-checking testbench for ec_add_pipe.
--
-- Feeds the PADD records from vectors_secp256k1.txt (generated by
-- gpu/ecc/ecref.py) into the point-adder as fast as it will take them, then
-- checks every (x3, y3) against the reference and confirms that results come
-- back on their originating tag.  It also measures the achieved issue rate,
-- which is the claim that matters for the architecture: one point addition
-- per 3 clocks, i.e. a fully saturated multiplier.
--
--   ghdl -a --std=08 fp_pkg.vhd fp_mul_secp256k1.vhd ec_add_pipe.vhd ec_add_tb.vhd
--   ghdl -e --std=08 ec_add_tb
--   ghdl -r --std=08 ec_add_tb

library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use std.textio.all;

use work.fp_pkg.all;

entity ec_add_tb is
  generic (
    VECTORS : string := "vectors_secp256k1.txt"
  );
end entity;

architecture sim of ec_add_tb is

  constant TAG_W  : natural := 8;
  constant MAXVEC : natural := 256;

  signal clk : std_logic := '0';
  signal rst : std_logic := '1';
  signal running : boolean := true;

  signal in_valid : std_logic := '0';
  signal in_ready : std_logic;
  signal in_x1, in_y1, in_x2, in_y2, in_inv : fp_t := (others => '0');
  signal in_tag : std_logic_vector(TAG_W - 1 downto 0) := (others => '0');
  signal out_valid : std_logic;
  signal out_x3, out_y3 : fp_t;
  signal out_tag : std_logic_vector(TAG_W - 1 downto 0);

  type vec_array_t is array (0 to MAXVEC - 1) of fp_t;
  signal x1v, y1v, x2v, y2v, iv, x3v, y3v : vec_array_t := (others => (others => '0'));
  signal nvec : natural := 0;
  signal loaded : boolean := false;

  signal errors  : natural := 0;
  signal checked : natural := 0;
  signal issued  : natural := 0;
  signal cycles  : natural := 0;
  signal counting : boolean := false;
  signal issue_cycles : natural := 0;

  function hex_to_fp (s : string) return fp_t is
    variable r : fp_t := (others => '0');
    variable d : natural;
  begin
    for i in s'range loop
      case s(i) is
        when '0' to '9' => d := character'pos(s(i)) - character'pos('0');
        when 'a' to 'f' => d := character'pos(s(i)) - character'pos('a') + 10;
        when 'A' to 'F' => d := character'pos(s(i)) - character'pos('A') + 10;
        when others     => d := 0;
      end case;
      r := shift_left(r, 4) or to_unsigned(d, W);
    end loop;
    return r;
  end function;

  function fp_to_hex (v : fp_t) return string is
    constant DIG : string(1 to 16) := "0123456789abcdef";
    variable s : string(1 to 64);
    variable n : natural;
  begin
    for i in 0 to 63 loop
      n := to_integer(v((63 - i) * 4 + 3 downto (63 - i) * 4));
      s(i + 1) := DIG(n + 1);
    end loop;
    return s;
  end function;

begin

  clk <= not clk after 5 ns when running else '0';

  dut : entity work.ec_add_pipe
    generic map (TAG_W => TAG_W, NSLOTS => 16)
    port map (
      clk => clk, rst => rst,
      in_valid => in_valid, in_ready => in_ready,
      in_x1 => in_x1, in_y1 => in_y1, in_x2 => in_x2, in_y2 => in_y2,
      in_inv => in_inv, in_tag => in_tag,
      out_valid => out_valid, out_x3 => out_x3, out_y3 => out_y3,
      out_tag => out_tag);

  loader : process
    file f       : text;
    variable ln  : line;
    variable st  : file_open_status;
    variable kind : string(1 to 5);
    variable h   : string(1 to 64);
    variable ch  : character;
    variable ok  : boolean;
    variable n   : natural := 0;

    impure function rd return fp_t is
    begin
      read(ln, ch, ok);          -- separating space
      read(ln, h, ok);
      return hex_to_fp(h);
    end function;
  begin
    file_open(st, f, VECTORS, read_mode);
    assert st = open_ok report "cannot open " & VECTORS severity failure;
    while not endfile(f) and n < MAXVEC loop
      readline(f, ln);
      if ln'length >= 5 then
        read(ln, kind, ok);
        if ok and kind = "PADD " then
          -- the 5-char read already consumed the trailing space
          read(ln, h, ok);
          x1v(n) <= hex_to_fp(h);
          y1v(n) <= rd;
          x2v(n) <= rd;
          y2v(n) <= rd;
          iv(n)  <= rd;
          x3v(n) <= rd;
          y3v(n) <= rd;
          n := n + 1;
        end if;
      end if;
    end loop;
    file_close(f);
    nvec <= n;
    wait for 1 ns;
    loaded <= true;
    report "loaded " & integer'image(n) & " PADD vectors";
    wait;
  end process;

  ticker : process (clk)
  begin
    if rising_edge(clk) and counting then
      cycles <= cycles + 1;
    end if;
  end process;

  driver : process
    variable i : natural := 0;
  begin
    wait until loaded;
    wait until rising_edge(clk);
    rst <= '0';
    wait until rising_edge(clk);
    counting <= true;
    while i < nvec loop
      in_valid <= '1';
      in_x1 <= x1v(i); in_y1 <= y1v(i);
      in_x2 <= x2v(i); in_y2 <= y2v(i);
      in_inv <= iv(i);
      in_tag <= std_logic_vector(to_unsigned(i mod 2 ** TAG_W, TAG_W));
      wait until rising_edge(clk);
      if in_ready = '1' then
        i := i + 1;
        issued <= i;
        issue_cycles <= cycles;
      end if;
    end loop;
    in_valid <= '0';
    for k in 0 to 4 * MUL_LATENCY + 32 loop
      wait until rising_edge(clk);
    end loop;
    counting <= false;

    assert checked = nvec
      report "expected " & integer'image(nvec) & " results, saw " & integer'image(checked)
      severity failure;
    report "ec_add_tb: " & integer'image(checked) & " point additions, "
           & integer'image(issue_cycles) & " clk to issue all of them ("
           & integer'image((issue_cycles * 10) / checked) & "/10 clk each), "
           & integer'image(cycles) & " clk including fill and drain";
    if errors = 0 then
      report "ec_add_tb: PASS";
    else
      report "ec_add_tb: FAIL -- " & integer'image(errors) & " mismatches"
        severity failure;
    end if;
    running <= false;
    wait;
  end process;

  checker : process (clk)
    variable idx : natural;
  begin
    if rising_edge(clk) then
      if out_valid = '1' then
        idx := to_integer(unsigned(out_tag));
        if out_x3 /= x3v(idx) or out_y3 /= y3v(idx) then
          report "PADD " & integer'image(idx) & " mismatch: x3 got "
                 & fp_to_hex(out_x3) & " want " & fp_to_hex(x3v(idx))
            severity error;
          errors <= errors + 1;
        end if;
        checked <= checked + 1;
      end if;
    end if;
  end process;

end architecture;
